#! env python
def log(s):
    print(s)

log('hello file')

if __name__ == '__main__':

    log('hello main')

class Logger:

    def __init__(self, level):
        self.log_method = print 
        self.level = level

    def log(self, s):
        self.log_method(s)

if __name__ == '__main__':

    mylog = Logger(0)
    mylog.log('in main')
